Confirmed: `orders.js:14-20` and `accounts.js:6-18` all key the `UPDATE` on `id` alone — any authenticated user can cancel, edit, or soft-delete another account's order or account by guessing/enumerating an id (IDOR / broken object-level authorization).

Fix: add `AND account_id = $n` to each query, bound to `req.user.accountId`, and treat a zero-row result as 404 (not a blind 200 with `null`/empty body).

```js
// orders.js
router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.sendStatus(404);
  res.json(row);
});
```

```js
// accounts.js
router.patch("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 AND id = $4 RETURNING *",
    [req.body.display_name, req.body.billing_email, req.params.id, req.user.accountId]
  );
  if (!row) return res.sendStatus(404);
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET deleted_at = now() WHERE id = $1 AND id = $2 RETURNING id",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.sendStatus(404);
  res.status(204).end();
});
```

(For accounts, `:id` is presumably the account itself, so the scoping check is really `req.params.id === req.user.accountId`, not a join column — same idea, just compare directly rather than adding a second column filter.) Same pattern applies to any other `UPDATE ... WHERE id = $1` in these two files you didn't show me — worth grepping for.

