No — this is a leak, not an undersized pool. `idle` stays at 0 while `waiting` climbs steadily every log line, meaning connections never come back to the pool.

The bug is in `db.js:11-16`: `client.release()` only runs if `fn(client)` succeeds. Any caller whose callback throws leaks that connection permanently. Raising `max` just delays the same exhaustion at a higher number.

Fix the leak first:

```js
async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}
```

db.js.text:
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.PGHOST,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

// Callers check out a client and are responsible for releasing it.
async function withClient(fn) {
  const client = await pool.connect();
  try {
    return await fn(client);
  } finally {
    client.release();
  }
}

module.exports = { pool, withClient };

